+/** Reuse only positive native evidence acquired inside this bounded context.
+ * The attachment is admission, not proof: actual source capabilities, covered
+ * scope/clock tokens and current target authority remain mandatory. The caller
+ * must fence both ends of acquisition and every externally visible use. */
+export async function createMaintainedEffectiveHistoryInvocationProof(source:D1Database,target:D1Database,
+  inputOwner:StorageCommunityOwner,sourceId:string,sourceNamespace:string,
+  scopes:readonly EffectiveDependencyScopeBounds[],deadlineMs:number):Promise<{
+    current():Promise<boolean>;close():void;logicalBytes():number;
+  }|undefined> {
+  const ctx=context(source),owner=Object.freeze({...inputOwner});
+  if(!ctx||source===target||ctx.target!==target||ctx.sourceId!==sourceId
+    ||ctx.sourceNamespace!==sourceNamespace||!owner.ownerDigest||!await available(ctx))return;
+  let captured=await createEffectiveDependencyReadContext(source,{participantId:owner.participantId,
+    ownerDigest:owner.ownerDigest,sourceId,sourceNamespace},scopes,deadlineMs);
+  if(!captured)return;
+  let closed=false;
+  // Upper bound on the owned logical context representation, not heap usage.
+  // Native tokens have exactly64 hexadecimal characters and safe integer
+  // expiries; generation and deadline are safe integers too. Every scope key
+  // is the exact canonical string held in the existing context's Map. Using
+  // MAX_SAFE_INTEGER supplies the greatest possible JSON integer width and
+  // retaining the scope request as well conservatively includes its metadata.
+  const identity={participantId:owner.participantId,ownerDigest:owner.ownerDigest,sourceId,sourceNamespace};
+  const scopeKeys=[...new Set(scopes.map(scope=>canonicalJson(scope)))];
+  const retainedBytes=new TextEncoder().encode(canonicalJson({owner,attachment:{sourceId,sourceNamespace},
+    request:scopes,context:{identity:canonicalJson(identity),generation:Number.MAX_SAFE_INTEGER,
+      expiresMs:Number.MAX_SAFE_INTEGER,tokens:scopeKeys.map(scopeKey=>[scopeKey,
+        {stamp:'f'.repeat(64),validUntilMs:Number.MAX_SAFE_INTEGER}])}})).byteLength;
+  const close=()=>{closed=true;captured=undefined;};
+  const current=async()=>{
+    // Only an in-flight check retains its snapshot after close. Releasing the
+    // handle's reference permits the opaque context's WeakMap state to be
+    // collected after that check settles, even if the closed handle is retained.
+    const snapshot=captured;
+    if(closed||!snapshot)return false;
+    try{
+      const valid=await available(ctx)&&await effectiveDependencyReadContextCurrent(source,snapshot,true)
+        &&await targetCurrent(ctx,owner)&&await effectiveDependencyReadContextCurrent(source,snapshot,true);
+      // A concurrent close or failed sibling check cannot be undone by this
+      // check finishing later. Native errors/budgets remain errors after release.
+      if(!valid||closed||captured!==snapshot){close();return false;}
+      return true;
+    }catch(error){close();throw error;}
+  };
+  const proof={current,close,logicalBytes(){return closed?0:retainedBytes;}};
+  if(!await proof.current()){proof.close();return;}
+  return proof;
